CREATE TABLE IF NOT EXISTS meetings (id TEXT PRIMARY KEY, secret TEXT NOT NULL, title TEXT NOT NULL, schedule TEXT NOT NULL, phase TEXT NOT NULL DEFAULT 'collect', agenda TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, meeting TEXT NOT NULL REFERENCES meetings(id), label TEXT NOT NULL, detail TEXT NOT NULL, kind TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS votes (meeting TEXT NOT NULL REFERENCES meetings(id), voter TEXT NOT NULL, pick1 TEXT NOT NULL DEFAULT '', pick2 TEXT NOT NULL DEFAULT '', PRIMARY KEY(meeting,voter));
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS starts_at TIMESTAMPTZ;
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS timezone TEXT NOT NULL DEFAULT 'UTC';
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS duration INTEGER NOT NULL DEFAULT 60;
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS location TEXT NOT NULL DEFAULT '';
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS sent TEXT NOT NULL DEFAULT '{}';
ALTER TABLE topics ADD COLUMN IF NOT EXISTS announced BOOLEAN NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS subscribers (id TEXT PRIMARY KEY, meeting TEXT NOT NULL REFERENCES meetings(id), email TEXT NOT NULL, token TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', invited BIGINT NOT NULL DEFAULT 0, UNIQUE(meeting,email));
CREATE TABLE IF NOT EXISTS ballots (topic TEXT NOT NULL REFERENCES topics(id), meeting TEXT NOT NULL REFERENCES meetings(id), voter TEXT NOT NULL, value SMALLINT NOT NULL, PRIMARY KEY(topic,voter));
INSERT INTO ballots (topic,meeting,voter,value) SELECT v.pick1,v.meeting,'c:'||v.voter,1 FROM votes v JOIN topics t ON t.id=v.pick1 ON CONFLICT DO NOTHING;
INSERT INTO ballots (topic,meeting,voter,value) SELECT v.pick2,v.meeting,'c:'||v.voter,1 FROM votes v JOIN topics t ON t.id=v.pick2 ON CONFLICT DO NOTHING;
DELETE FROM votes;
ALTER TABLE topics ADD COLUMN IF NOT EXISTS author TEXT NOT NULL DEFAULT '';
ALTER TABLE topics ADD COLUMN IF NOT EXISTS hidden BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE subscribers ADD COLUMN IF NOT EXISTS voter TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, meeting TEXT NOT NULL, recipient TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, created BIGINT NOT NULL, updated BIGINT NOT NULL, error TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS outbox_status ON outbox (status, created);
CREATE TABLE IF NOT EXISTS rate_events (key TEXT NOT NULL, at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS rate_events_key ON rate_events (key, at)
;
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'member', status TEXT NOT NULL DEFAULT 'invited', emails TEXT NOT NULL DEFAULT 'all', token TEXT NOT NULL UNIQUE, created BIGINT NOT NULL, invited BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, created BIGINT NOT NULL, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS signin_codes (id TEXT PRIMARY KEY, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, expires BIGINT NOT NULL, used BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS rsvps (meeting TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, status TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', updated BIGINT NOT NULL, PRIMARY KEY(meeting,member));
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS repeat TEXT NOT NULL DEFAULT '';
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS created BIGINT NOT NULL DEFAULT 0;
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS next_meeting TEXT NOT NULL DEFAULT '';
INSERT INTO members (id,email,name,role,status,token,created) SELECT DISTINCT ON (email) id,email,'','member','active',token,invited FROM subscribers WHERE status='active' ORDER BY email,invited ON CONFLICT DO NOTHING;
UPDATE subscribers SET status='migrated' WHERE status='active'
;
UPDATE ballots b SET voter='m:'||substr(b.voter,3) WHERE b.voter LIKE 's:%' AND EXISTS (SELECT 1 FROM members m WHERE m.id=substr(b.voter,3)) AND NOT EXISTS (SELECT 1 FROM ballots x WHERE x.topic=b.topic AND x.voter='m:'||substr(b.voter,3))
;
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, author TEXT NOT NULL REFERENCES members(id), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', pinned BOOLEAN NOT NULL DEFAULT false, hidden BOOLEAN NOT NULL DEFAULT false, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, kind TEXT NOT NULL, target TEXT NOT NULL, author TEXT NOT NULL REFERENCES members(id), body TEXT NOT NULL, via TEXT NOT NULL DEFAULT 'web', hidden BOOLEAN NOT NULL DEFAULT false, created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS comments_target ON comments (kind, target, created);
CREATE TABLE IF NOT EXISTS reply_keys (key TEXT PRIMARY KEY, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, kind TEXT NOT NULL, target TEXT NOT NULL, created BIGINT NOT NULL, UNIQUE(member,kind,target));
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
ALTER TABLE members ADD COLUMN IF NOT EXISTS digest TEXT NOT NULL DEFAULT 'daily';
ALTER TABLE members ADD COLUMN IF NOT EXISTS digest_at BIGINT NOT NULL DEFAULT 0
;
CREATE TABLE IF NOT EXISTS actions (id TEXT PRIMARY KEY, meeting TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, title TEXT NOT NULL, owner TEXT REFERENCES members(id) ON DELETE SET NULL, due TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', created BIGINT NOT NULL, done_at BIGINT NOT NULL DEFAULT 0, reminded TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS actions_open ON actions (status, due);
ALTER TABLE members ADD COLUMN IF NOT EXISTS feed TEXT NOT NULL DEFAULT '';
ALTER TABLE topics ADD COLUMN IF NOT EXISTS carried_from TEXT NOT NULL DEFAULT ''
;
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'Event', starts_at TIMESTAMPTZ NOT NULL, duration INTEGER NOT NULL DEFAULT 120, timezone TEXT NOT NULL DEFAULT 'UTC', location TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', author TEXT REFERENCES members(id) ON DELETE SET NULL, hidden BOOLEAN NOT NULL DEFAULT false, announced BOOLEAN NOT NULL DEFAULT false, created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS events_start ON events (starts_at);
CREATE TABLE IF NOT EXISTS slots (id TEXT PRIMARY KEY, event TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, label TEXT NOT NULL, starts_at TIMESTAMPTZ, duration INTEGER NOT NULL DEFAULT 0, capacity INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, reminded BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS claims (slot TEXT NOT NULL REFERENCES slots(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, created BIGINT NOT NULL, PRIMARY KEY(slot,member))
;
CREATE TABLE IF NOT EXISTS calls (id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'Other', organization TEXT NOT NULL DEFAULT '', deadline TEXT NOT NULL, link TEXT NOT NULL DEFAULT '', award TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '', author TEXT REFERENCES members(id) ON DELETE SET NULL, hidden BOOLEAN NOT NULL DEFAULT false, created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS calls_deadline ON calls (deadline);
CREATE TABLE IF NOT EXISTS call_interest (call TEXT NOT NULL REFERENCES calls(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, status TEXT NOT NULL, reminded TEXT NOT NULL DEFAULT '', updated BIGINT NOT NULL, PRIMARY KEY(call,member));
CREATE TABLE IF NOT EXISTS going (event TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, created BIGINT NOT NULL, PRIMARY KEY(event,member))
;
CREATE TABLE IF NOT EXISTS proposals (id TEXT PRIMARY KEY, number INTEGER NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'Other', figure TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', effect TEXT NOT NULL DEFAULT '', days INTEGER NOT NULL DEFAULT 7, author TEXT REFERENCES members(id) ON DELETE SET NULL, seconder TEXT REFERENCES members(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'draft', created BIGINT NOT NULL, opened BIGINT, closes_at BIGINT, closed_at BIGINT, reminded BOOLEAN NOT NULL DEFAULT false, for_n INTEGER NOT NULL DEFAULT 0, against_n INTEGER NOT NULL DEFAULT 0, abstain_n INTEGER NOT NULL DEFAULT 0, eligible INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS proposals_status ON proposals (status, closes_at);
CREATE TABLE IF NOT EXISTS proposal_votes (proposal TEXT NOT NULL REFERENCES proposals(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, vote TEXT NOT NULL, updated BIGINT NOT NULL, PRIMARY KEY(proposal,member))
;
ALTER TABLE members ADD COLUMN IF NOT EXISTS medium TEXT NOT NULL DEFAULT '';
ALTER TABLE members ADD COLUMN IF NOT EXISTS title TEXT NOT NULL DEFAULT ''
;
CREATE TABLE IF NOT EXISTS checkins (member TEXT PRIMARY KEY REFERENCES members(id) ON DELETE CASCADE, at BIGINT NOT NULL)
;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS tag TEXT NOT NULL DEFAULT 'General';
CREATE TABLE IF NOT EXISTS post_plus (post TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, created BIGINT NOT NULL, PRIMARY KEY(post,member))
;
ALTER TABLE calls ADD COLUMN IF NOT EXISTS eligibility TEXT NOT NULL DEFAULT '';
ALTER TABLE calls ADD COLUMN IF NOT EXISTS results TEXT NOT NULL DEFAULT '';
ALTER TABLE calls ADD COLUMN IF NOT EXISTS needs TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS call_checks (call TEXT NOT NULL REFERENCES calls(id) ON DELETE CASCADE, member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, item INTEGER NOT NULL, PRIMARY KEY(call,member,item))
;
ALTER TABLE members ADD COLUMN IF NOT EXISTS notify_meetings BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE members ADD COLUMN IF NOT EXISTS notify_proposals BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE members ADD COLUMN IF NOT EXISTS notify_calls BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE members ADD COLUMN IF NOT EXISTS notify_signups BOOLEAN NOT NULL DEFAULT true
;
CREATE TABLE IF NOT EXISTS rate_counts (key TEXT NOT NULL, bucket BIGINT NOT NULL, n INTEGER NOT NULL, expires BIGINT NOT NULL, PRIMARY KEY(key,bucket));
ALTER TABLE signin_codes ADD COLUMN IF NOT EXISTS short BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS replies_seen (id TEXT PRIMARY KEY, at BIGINT NOT NULL)
